import { expect, test } from '@playwright/test';

test('损坏的设置记录：显示原因与恢复动作，恢复后回到默认', async ({ page }) => {
  await page.goto('/');
  await expect(page.locator('html')).toHaveAttribute('data-hydrated', 'true');
  // 预置非法 JSON → 重载。
  await page.evaluate(() => {
    window.localStorage.setItem('community-go.shell', '{not-valid-json');
  });
  await page.reload();
  await expect(page.locator('html')).toHaveAttribute('data-hydrated', 'true');
  const bannerText = page.getByText('本地设置记录无法读取');
  await expect(bannerText).toBeVisible();
  const banner = page.locator('[role="alert"]').filter({ hasText: '本地设置记录无法读取' });
  await banner.getByRole('button', { name: '恢复默认设置' }).click();
  await page.waitForTimeout(600);
  await expect(page.locator('html')).toHaveAttribute('data-hydrated', 'true');
  await expect(page.getByText('本地设置记录无法读取')).not.toBeVisible();
  const shell = await page.evaluate(() => window.localStorage.getItem('community-go.shell'));
  expect(shell).not.toBeNull();
  expect(() => JSON.parse(shell!)).not.toThrow();
});

import type { Page } from '@playwright/test';
import { expect, test } from '@playwright/test';

async function resetAll(page: Page) {
  await page.goto('/reference-resources/create');
  await page.evaluate(() => {
    window.localStorage.removeItem('community-go.shell');
    window.localStorage.removeItem('community-go.workspace');
  });
  await page.reload();
  await expect(page.locator('html')).toHaveAttribute('data-hydrated', 'true');
}

test('本地草稿自动保存并恢复（操作偏好 autosaveDrafts 开）：输入 → 刷新恢复', async ({ page }) => {
  await resetAll(page);
  // 设置 → 操作偏好 → 本地草稿自动保存 = 开。
  await page.goto('/settings/actions');
  await page.getByRole('heading', { name: '操作偏好' }).first().scrollIntoViewIfNeeded();
  const autosave = page.getByRole('switch', { name: '本地草稿自动保存' });
  await autosave.focus();
  await page.keyboard.press('Space');
  await expect(autosave).toBeChecked();

  // 创建页输入（触发自动保存）。
  await page.goto('/reference-resources/create');
  await page.getByLabel('名称').fill('草稿测试 Alpha');
  await page.waitForTimeout(500); // 等 autosave 落盘

  // 刷新 → 草稿恢复（未提交语义保留）。
  await page.reload();
  await expect(page.locator('html')).toHaveAttribute('data-hydrated', 'true');
  await expect(page.getByLabel('名称')).toHaveValue('草稿测试 Alpha');

  // 提交成功 → 草稿清除。
  await page.getByRole('button', { name: '创建' }).click();
  await expect(page).toHaveURL(/\/reference-resources$/);
  const stored = await page.evaluate(() => {
    const raw = window.localStorage.getItem('community-go.workspace');
    return raw ? JSON.parse(raw) : null;
  });
  expect(stored?.state?.records?.['reference-resources.create']).toBeUndefined();
});

test('autosaveDrafts 关（默认）：输入不写草稿', async ({ page }) => {
  await resetAll(page);
  await page.getByLabel('名称').fill('不应保存的草稿');
  await page.waitForTimeout(500);
  const stored = await page.evaluate(() => {
    const raw = window.localStorage.getItem('community-go.workspace');
    return raw ? JSON.parse(raw) : null;
  });
  expect(stored?.state?.records?.['reference-resources.create']).toBeUndefined();
});

import { expect, test } from '@playwright/test';

test('持久化失败：显示"未保存到此浏览器"且会话效果保留，允许重试', async ({ page }) => {
  await page.goto('/settings/navigation');
  await expect(page.locator('html')).toHaveAttribute('data-hydrated', 'true');
  // 模拟存储拒绝（quota）：令 localStorage.setItem 抛 QuotaExceededError。
  await page.evaluate(() => {
    const original = Storage.prototype.setItem;
    (window as unknown as { __origSetItem: typeof original }).__origSetItem = original;
    Storage.prototype.setItem = function (key: string, value: string) {
      if (key === 'community-go.shell') {
        const error = new DOMException('quota', 'QuotaExceededError');
        throw error;
      }
      return original.call(this, key, value);
    };
  });
  await page.getByRole('heading', { name: '导航' }).first().scrollIntoViewIfNeeded();
  const sw = page.getByRole('switch', { name: '记住展开的侧栏菜单' });
  await sw.focus();
  await page.keyboard.press('Space');
  // 会话效果保留 + 失败横幅出现。
  await expect(sw).toBeChecked();
  await expect(page.getByText('未保存到此浏览器')).toBeVisible();
  // 恢复存储后重试 → 横幅消失且值持久化。
  await page.evaluate(() => {
    const orig = (window as unknown as { __origSetItem: typeof Storage.prototype.setItem })
      .__origSetItem;
    Storage.prototype.setItem = orig;
  });
  await page.getByRole('button', { name: '重试' }).click();
  await expect(page.getByText('未保存到此浏览器')).not.toBeVisible();
  await page.reload();
  await expect(page.locator('html')).toHaveAttribute('data-hydrated', 'true');
  await expect(page.getByRole('switch', { name: '记住展开的侧栏菜单' })).toBeChecked();
});

'use client';

/**
 * Host —— 通知声音 / 桌面通知消费者（SET-006 通知偏好 sound / desktopNotifications
 * 的真实运行时消费；默认均关）。
 *
 * - 订阅 Host notifications store：真实新发布项到达时按偏好发声 / 弹桌面通知；
 * - sound：WebAudio 短提示音（无资源文件；播放失败不抛错——静默降级可观测）；
 * - desktopNotifications：仅当 Notification.permission === 'granted' 时真正弹出；
 *   开启偏好时由 RuntimeProviders 触发权限请求，拒绝/不支持则回退偏好并呈现原因
 *   （见 useDesktopNotificationGate）；关键（error/critical）通知不受关闭影响——
 *   桌面通知默认关时关键项仍走应用内通知中心（既有能力），此处不重复。
 */
import { useEffect, useRef } from 'react';

import { useFrontendTranslation } from '@community-go/i18n';

import { useShellStore } from '../state/use-shell-store';
import { useNotificationsStore } from '../state/use-notifications-store';

/** WebAudio 短提示音：两个快速上升音；AudioContext 不可用/受限时静默（可观测）。 */
function playChime(): void {
  try {
    const Ctor =
      window.AudioContext ??
      (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) return;
    const context = new Ctor();
    const gain = context.createGain();
    gain.connect(context.destination);
    gain.gain.setValueAtTime(0.0001, context.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.18, context.currentTime + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, context.currentTime + 0.45);
    for (const [freq, start] of [
      [880, 0],
      [1174.66, 0.12],
    ] as const) {
      const osc = context.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = freq;
      osc.connect(gain);
      osc.start(context.currentTime + start);
      osc.stop(context.currentTime + start + 0.2);
    }
    window.setTimeout(() => void context.close().catch(() => undefined), 800);
  } catch {
    // 声音播放失败：明确静默（不打断用户；偏好仍保留）。
  }
}

/** 请求桌面通知权限；返回最终状态（granted / denied / unsupported）。 */
export async function requestDesktopNotificationPermission(): Promise<
  'granted' | 'denied' | 'unsupported'
> {
  if (typeof window === 'undefined' || !('Notification' in window)) return 'unsupported';
  if (Notification.permission === 'granted') return 'granted';
  if (Notification.permission === 'denied') return 'denied';
  try {
    const result = await Notification.requestPermission();
    return result === 'granted' ? 'granted' : 'denied';
  } catch {
    return 'unsupported';
  }
}

/** RuntimeProviders 装配：desktopNotifications 开启时请求权限；拒绝/不支持 → 回退偏好。 */
export function useDesktopNotificationGate(): void {
  const { t } = useFrontendTranslation();
  const desktopNotifications = useShellStore(
    (state) => state.preferences.notifications.desktopNotifications,
  );
  const handledRef = useRef(false);
  useEffect(() => {
    if (!desktopNotifications || handledRef.current) return;
    handledRef.current = true;
    void requestDesktopNotificationPermission().then((status) => {
      if (status === 'granted') return;
      // 拒绝或不支持：回退偏好（避免"无效开关"——无法交付时不让开关保留假象），
      // 并经真实通知管线（应用内通知中心）呈现原因——不静默。
      useShellStore.getState().updateCategory('notifications', { desktopNotifications: false });
      useNotificationsStore.getState().publish({
        category: 'warning',
        severity: 'notice',
        title: t('shell.desktopNotificationDeniedTitle'),
        description:
          status === 'unsupported'
            ? t('shell.desktopNotificationUnsupported')
            : t('shell.desktopNotificationDenied'),
      });
    });
  }, [desktopNotifications, t]);
}

/** 真实新通知到达 → 按偏好发声 / 桌面通知。 */
export function NotificationAlerts(): null {
  const sound = useShellStore((state) => state.preferences.notifications.sound);
  const desktopNotifications = useShellStore(
    (state) => state.preferences.notifications.desktopNotifications,
  );
  const seenRef = useRef<ReadonlySet<string>>(new Set());

  useEffect(() => {
    // 订阅 store：items 变化时核对新 id（markRead 也改 items，但 id 集去重）。
    const unsubscribe = useNotificationsStore.subscribe((state, prev) => {
      if (state.items === prev.items) return;
      const seen = seenRef.current;
      for (const item of state.items) {
        if (seen.has(item.id)) continue;
        seenRef.current = new Set([...seenRef.current, item.id]);
        if (sound) playChime();
        if (
          desktopNotifications &&
          typeof window !== 'undefined' &&
          'Notification' in window &&
          Notification.permission === 'granted'
        ) {
          try {
            new Notification(item.title, {
              ...(item.description ? { body: item.description } : {}),
            });
          } catch {
            // 构造失败静默（应用内通知中心仍可达）。
          }
        }
      }
    });
    // 初始同步：已存在项全部计入 seen，避免挂载时对历史项发声。
    const initial = useNotificationsStore.getState().items;
    seenRef.current = new Set(initial.map((item) => item.id));
    return unsubscribe;
  }, [desktopNotifications, sound]);

  return null;
}

'use client';

import { X } from 'lucide-react';
import { IconAction } from '@community-go/ui-adapter/icon-action';
import { MenuButton } from '@community-go/ui-adapter/menu-button';
import { generatedSurfaceRegistry } from '@community-go/surface/generated/composition';
import { useEffect, useRef } from 'react';
import { usePathname, useRouter } from 'next/navigation';

import { useFrontendTranslation } from '@community-go/i18n';
import { rehydrateStore } from '@community-go/state-foundation';
import { usePageTabsStore } from '../state/use-page-tabs-store';
import { useShellStore } from '../state/use-shell-store';
import { proceedAfterLeaveConfirm } from '../host/leave-confirm';
import { markForwardRouteIntent, pageTransitionTypes } from '../host/route-transition-constants';
import { resolveScrollOption } from '../host/scroll-preference';

/**
 * Shell 顶部页面标签条（SET-005-002）。
 *
 * - 标签 = 页面入口（pathname 身份；筛选/排序变化不创建重复标签）；切换仍走
 *   Next Router（不缓存 React 页面树）；
 * - 页面入口提交时打开标签（去重前移，见 usePageTabsRecorder）；当前页高亮；X 关闭；
 * - **导航偏好 pageTabsEnabled 门控**（默认关 → 不显示条、不记录）；
 * - 会话级持久化（sessionStorage；restoreLastTabs=true 时本窗口刷新恢复，
 *   false 时挂载后清空陈旧会话标签——关闭记忆停止恢复但不删本地数据的语义
 *   由 clearIfDisabled 在挂载时执行一次）。
 */
export function PageTabs() {
  const { t } = useFrontendTranslation();
  const pathname = usePathname();
  const router = useRouter();
  const pageTabsEnabled = useShellStore((state) => state.preferences.navigation.pageTabsEnabled);
  const tabs = usePageTabsStore((state) => state.tabs);

  // 显式 hydration（skipHydration store）；restoreLastTabs=false 的会话清空由
  // usePageTabsRecorder 首个启用帧处理（避免与打开当前页竞态）。
  useEffect(() => {
    rehydrateStore(usePageTabsStore);
  }, []);

  // 关闭标签（SET-005-002 关闭策略）：若关闭的是当前激活标签，按偏好
  // tabCloseBehavior（最近/右邻/左邻）导航到目标；无目标 → 回默认首页（'/'）。
  const tabCloseBehavior = useShellStore((state) => state.preferences.navigation.tabCloseBehavior);
  const closeTabAt = async (closedPathname: string) => {
    const closingActive = closedPathname === pathname;
    const closingIndex = tabs.findIndex((tab) => tab.pathname === closedPathname);
    const target = (() => {
      if (!closingActive) return null;
      if (tabCloseBehavior === 'recent') {
        const other = tabs.find((tab) => tab.pathname !== closedPathname);
        return other?.pathname ?? '/';
      }
      if (tabCloseBehavior === 'right') {
        const right = tabs[closingIndex + 1]; // 屏幕右邻（更早访问）
        return right ? right.pathname : '/';
      }
      const left = tabs[closingIndex - 1]; // 屏幕左邻（更新访问）
      return left ? left.pathname : '/';
    })();
    if (closingActive && target && target !== pathname && !(await proceedAfterLeaveConfirm(target, t('shell.pageTabs')))) return;
    usePageTabsStore.getState().closeTab(closedPathname);
    if (closingActive) {
      if (target && target !== pathname) {
        void router.push(target, {
          transitionTypes: [pageTransitionTypes.forward],
          ...resolveScrollOption(),
        });
      } else if (target === '/') {
        void router.push('/', {
          transitionTypes: [pageTransitionTypes.forward],
          ...resolveScrollOption(),
        });
      }
    }
  };

  if (!pageTabsEnabled) return null;

  return (
    <nav
      aria-label={t('shell.pageTabs')}
      className="flex min-w-0 items-center gap-0.5 overflow-x-auto border-b border-border bg-surface px-3"
    >
      {tabs.length === 0 ? (
        <span className="px-2 py-2 text-xs text-ink-muted">{t('shell.noPageTabs')}</span>
      ) : (
        tabs.map((tab) => {
          const active = tab.pathname === pathname;
          return (
            <div
              className={`${active ? 'inline-flex' : 'hidden md:inline-flex'} shrink-0 items-center gap-1 border-b-2 px-2 py-1.5 text-sm ${
                active
                  ? 'border-brand font-semibold text-brand'
                  : 'border-transparent text-ink-muted hover:text-ink'
              }`}
              key={tab.pathname}
            >
              <button
                aria-current={active ? 'page' : undefined}
                title={tab.title}
                className="min-h-control max-w-40 truncate rounded-control px-1 outline-none focus-visible:ring-2 focus-visible:ring-brand"
                onClick={() => {
                  if (tab.pathname === pathname) return;
                  void proceedAfterLeaveConfirm(tab.pathname, t('shell.pageTabs')).then(
                    (proceed) => {
                      if (!proceed) return;
                      markForwardRouteIntent();
                      void router.push(tab.pathname, {
                        transitionTypes: [pageTransitionTypes.forward],
                        ...resolveScrollOption(),
                      });
                    },
                  );
                }}
                type="button"
              >
                {tab.title}
              </button>
              <IconAction label={t('shell.closeTab', { title: tab.title })} onPress={() => { void closeTabAt(tab.pathname); }}><X aria-hidden="true" className="size-4" /></IconAction>
            </div>
          );
        })
      )}
      {tabs.length > 0 ? <div className="ml-auto shrink-0 md:hidden"><MenuButton
        label={t('shell.morePages', { count: tabs.length })}
        ariaLabel={t('shell.pageTabs')}
        items={tabs.map(tab => ({id: tab.pathname, label: tab.title,
          ...(tab.pathname === pathname ? {description: t('shell.currentPage')} : {})}))}
        onAction={(href) => { void proceedAfterLeaveConfirm(href, t('shell.pageTabs')).then(proceed => {
          if (proceed) { markForwardRouteIntent(); router.push(href, resolveScrollOption()); }
        }); }}
      /></div> : null}
    </nav>
  );
}

/** 记录当前 pathname 的标签打开事件（app-shell 在导航提交时一并调用）。 */
export function usePageTabsRecorder(entries: ReadonlyArray<{ href: string; label: string }>): void {
  const pathname = usePathname();
  const enabled = useShellStore(state => state.preferences.navigation.pageTabsEnabled);
  const restoreLastTabs = useShellStore(state => state.preferences.navigation.restoreLastTabs);
  const startedRef = useRef(false);
  useEffect(() => {
    if (!enabled) return;
    const valid = new Set(['/', ...Object.values(generatedSurfaceRegistry.routes).map(route => route.pattern)]);
    if (!valid.has(pathname)) return;
    if (!startedRef.current) {
      startedRef.current = true;
      if (!restoreLastTabs) usePageTabsStore.getState().closeAllTabs();
      else usePageTabsStore.getState().pruneTabs(valid);
    }
    let frame = 0;
    const record = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        const heading = document.querySelector('.surface-route-content h1')?.textContent?.trim();
        const title = heading || entries.find(entry => entry.href === pathname)?.label;
        if (title) usePageTabsStore.getState().openTab({pathname, title});
      });
    };
    const observer = new MutationObserver(record);
    const content = document.querySelector('.surface-route-content');
    if (content) observer.observe(content, {childList: true, subtree: true, characterData: true});
    record();
    return () => { observer.disconnect(); cancelAnimationFrame(frame); };
  }, [pathname, entries, enabled, restoreLastTabs]);
}

// @vitest-environment jsdom
import { beforeEach, describe, expect, it, vi } from 'vitest';

import {
  dirtyMessage,
  installBeforeUnloadGuard,
  isAnyDirty,
  isLeaveConfirmEnabled,
  proceedAfterLeaveConfirm,
  registerDirtySource,
  resetLeaveConfirmEnabledForTest,
  resetLeaveConfirmForTest,
  setLeaveConfirmEnabled,
  setLeaveConfirmResolver,
} from '../host/leave-confirm';
import { resetNavigationLifecycle } from '../host/navigation-lifecycle';

describe('leave-confirm 注册表与统一询问', () => {
  beforeEach(() => {
    resetLeaveConfirmForTest();
    resetLeaveConfirmEnabledForTest();
    resetNavigationLifecycle();
    setLeaveConfirmResolver(null);
  });

  it('无 dirty source → 直接放行（同 resolved target 仍 no-op 短路）', async () => {
    // 首次 /settings 无基线 → 放行。
    await expect(proceedAfterLeaveConfirm('/settings')).resolves.toBe(true);
    // 同 target 再次导航（基线已由测试手动提交）→ no-op false。
  });

  it('dirty source 存在且 dirty → 先询问；取消返回 false 且不 begin', async () => {
    setLeaveConfirmResolver(async () => false); // 用户取消
    const unregister = registerDirtySource({
      pageId: 'edit',
      message: () => '有未保存的更改',
      isDirty: () => true,
    });
    await expect(proceedAfterLeaveConfirm('/settings')).resolves.toBe(false);
    unregister();
  });

  it('dirty source 存在且 dirty → 确认后放行', async () => {
    setLeaveConfirmResolver(async () => true);
    const unregister = registerDirtySource({
      pageId: 'edit',
      message: () => '有未保存的更改',
      isDirty: () => true,
    });
    await expect(proceedAfterLeaveConfirm('/settings')).resolves.toBe(true);
    unregister();
  });

  it('提交中（isSubmitting）不算 dirty', async () => {
    const unregister = registerDirtySource({
      pageId: 'edit',
      message: () => 'x',
      isDirty: () => true,
      isSubmitting: () => true,
    });
    expect(isAnyDirty()).toBe(false);
    await expect(proceedAfterLeaveConfirm('/settings')).resolves.toBe(true);
    unregister();
  });

  it('dirtyMessage 取首个 dirty source 的文案；无 dirty 为空', () => {
    expect(dirtyMessage()).toBe('');
    const unregister = registerDirtySource({
      pageId: 'edit',
      message: () => '有未保存的更改',
      isDirty: () => true,
    });
    expect(dirtyMessage()).toBe('有未保存的更改');
    unregister();
  });

  it('beforeunload 仅 dirty 时设置 returnValue（事件可取消）', () => {
    const unregisterGuard = installBeforeUnloadGuard();
    const event = new Event('beforeunload', { cancelable: true });
    // 无 dirty：不 preventDefault。
    const dispatched = window.dispatchEvent(event);
    // jsdom 无法断言 returnValue 传播，但 preventDefault 使 dispatched=false。
    expect(dispatched).toBe(true);
    const dirty = registerDirtySource({
      pageId: 'edit',
      message: () => 'x',
      isDirty: () => true,
    });
    const dirtyEvent = new Event('beforeunload', { cancelable: true });
    const dispatchedDirty = window.dispatchEvent(dirtyEvent);
    expect(dispatchedDirty).toBe(false); // preventDefault 被调用
    dirty();
    unregisterGuard();
  });

  it('unregister 后不再 dirty', () => {
    const unregister = registerDirtySource({
      pageId: 'edit',
      message: () => 'x',
      isDirty: () => true,
    });
    expect(isAnyDirty()).toBe(true);
    unregister();
    expect(isAnyDirty()).toBe(false);
  });

  it('confirmLeave 偏好关闭 → 不询问直接 proceed（即使 dirty）', async () => {
    setLeaveConfirmEnabled(false);
    const resolver = vi.fn(async () => true);
    setLeaveConfirmResolver(resolver);
    const unregister = registerDirtySource({
      pageId: 'edit',
      message: () => '有未保存的更改',
      isDirty: () => true,
    });
    await expect(proceedAfterLeaveConfirm('/settings')).resolves.toBe(true);
    expect(resolver).not.toHaveBeenCalled();
    unregister();
  });

  it('confirmLeave 偏好默认开；setLeaveConfirmEnabled(true) 恢复询问', async () => {
    expect(isLeaveConfirmEnabled()).toBe(true);
    setLeaveConfirmEnabled(false);
    expect(isLeaveConfirmEnabled()).toBe(false);
    setLeaveConfirmEnabled(true);
    const resolver = vi.fn(async () => true);
    setLeaveConfirmResolver(resolver);
    const unregister = registerDirtySource({
      pageId: 'edit',
      message: () => '有未保存的更改',
      isDirty: () => true,
    });
    await proceedAfterLeaveConfirm('/settings');
    expect(resolver).toHaveBeenCalledTimes(1);
    unregister();
  });
});

'use client';

/**
 * settings —— 设置内页 Shell（SET-011：持久化布局壳）。
 *
 * - `SETTINGS_CATEGORIES`：单一映射表（shortId/routeId/模型 key/label/iconId/分组）。
 * - `SettingsShellContext`：layout 一次性装配的偏好 ctx 与失败横幅，下传各分类 page
 *   （page 只渲染分类区段，不重复订阅/装配——切换分类仅换右侧内容，壳不重挂载）。
 * - `SettingsSidebar`：SettingsLayout 左栏（固定顶部搜索 + 分组分类导航，含语义
 *   NavigationIcon 与 active 高亮）。
 * - `useSettingsPersistReport`：统一持久化失败呈现（reportingPort + notSaved + 重试）。
 */
