            {SETTINGS_CATEGORIES.filter((meta) => meta.group === groupMeta.group).map((meta) => (
              <NavItem active={active} key={meta.shortId} meta={meta} {...(onNavigate ? { onNavigate } : {})} />
            ))}
          </div>
        ))}
      </nav>
    </Panel>
  );
}

